import{_ as a,C as s,o as n,c as r,j as t,a as d,E as i,a6 as h}from"./chunks/framework.CCKCzdWs.js";const y=JSON.parse('{"title":"Guides","description":"Step-by-step walkthroughs of common tasks on your own dashboard, from reporting a first run to the Flake Lab, opened from the command palette, with no AI model.","frontmatter":{"title":"Guides","description":"Step-by-step walkthroughs of common tasks on your own dashboard, from reporting a first run to the Flake Lab, opened from the command palette, with no AI model.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/guides.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/guides.html"}],["meta",{"property":"og:title","content":"Guides | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Step-by-step walkthroughs of common tasks on your own dashboard, from reporting a first run to the Flake Lab, opened from the command palette, with no AI model."}]]},"headers":[],"relativePath":"features/guides.md","filePath":"features/guides.md","lastUpdated":1793385976000}'),l={name:"features/guides.md"};function u(g,e,p,c,m,f){const o=s("Needs");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"guides",tabindex:"-1"},[d("Guides "),t("a",{class:"header-anchor",href:"#guides","aria-label":'Permalink to "Guides"'},"​")],-1)),i(o,{reporter:""}),e[1]||(e[1]=h('<p>A guide walks you through one task on your own dashboard: a popover on each part of the screens the task uses, in order, each with a link to the docs page that explains it. The guides are written in advance, so they need no AI model and work on every instance, the same way each time.</p><h2 id="opening-a-guide" tabindex="-1">Opening a guide <a class="header-anchor" href="#opening-a-guide" aria-label="Permalink to &quot;Opening a guide&quot;">​</a></h2><p>Open the command palette (<code>Ctrl</code> + <code>K</code>, <code>⌘</code> + <code>K</code> on macOS) and pick a guide under <strong>Guides</strong>, or type the task: a guide is also found by words such as <em>ollama</em>, <em>slack</em> or <em>selector</em>. The <a href="./assistant.html">assistant</a> panel lists them too when its conversation is empty, and when no AI model is configured; starting one closes the panel.</p><p><strong>Next</strong> and <strong>Back</strong> move between the stops, opening the page each one is on. <strong>×</strong> or <code>Esc</code> ends the guide, and so does going to another page yourself. While a stop shows, the part it points at cannot be clicked: a guide shows the dashboard and changes nothing.</p><h2 id="following-the-way" tabindex="-1">Following the way <a class="header-anchor" href="#following-the-way" aria-label="Permalink to &quot;Following the way&quot;">​</a></h2><p>A guide takes the way you would take yourself, and shows it. Before it opens another page, a tab, a folded section or a menu, it points for a moment at the link or the button that does it, when that link is on the screen: an entry of the sidebar, a row of a list, a tab. The line at the top of each popover says where the stop is: the page&#39;s breadcrumb, then the tab and the section it sits in, the ones the guide just opened in color.</p><p>When a stop explains several parts of the screen, it numbers them: each number on the page matches one line of the popover, and pointing at a line enlarges its number on the page.</p><h2 id="the-guides" tabindex="-1">The guides <a class="header-anchor" href="#the-guides" aria-label="Permalink to &quot;The guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Guide</th><th>What it shows</th><th>Listed for</th></tr></thead><tbody><tr><td><strong>Report a first run</strong></td><td>Install the reporter, send a run, and find it in its project</td><td>Administrators</td></tr><tr><td><strong>Configure AI</strong></td><td>Choose the models behind diagnosis and the assistant</td><td>Administrators</td></tr><tr><td><strong>Add the SCM token</strong></td><td>Let Piwi read the commits behind a failure</td><td>Project admins</td></tr><tr><td><strong>Set up CI and sharding</strong></td><td>Report from CI, merge shards into one run, re-run from a cluster</td><td>Administrators</td></tr><tr><td><strong>Turn on pull-request feedback</strong></td><td>Post each run&#39;s result on its pull request</td><td>Administrators</td></tr><tr><td><strong>Connect Jira</strong></td><td>File issues from failures and keep them in sync</td><td>Administrators</td></tr><tr><td><strong>Set up notifications</strong></td><td>Send failures to email, Slack, Teams or a webhook</td><td>Everyone</td></tr><tr><td><strong>Grant roles and groups</strong></td><td>Add users, group them and give them project roles</td><td>Administrators</td></tr><tr><td><strong>Add the capture fixtures</strong></td><td>Record requests, console and Web Vitals from inside your tests</td><td>Everyone</td></tr><tr><td><strong>Connect an MCP client</strong></td><td>Let Claude Code, Cursor or VS Code read your results</td><td>Everyone</td></tr><tr><td><strong>Schedule a quality report</strong></td><td>Send a dashboard&#39;s report on a cadence, and keep each one</td><td>Contributors and up</td></tr><tr><td><strong>Run the Flake Lab</strong></td><td>Make a flaky test fail on demand, then prove the fix</td><td>Everyone</td></tr><tr><td><strong>Apply a locator fix</strong></td><td>Replace a broken locator with the one healing recommends</td><td>Everyone</td></tr><tr><td><strong>Build a dashboard</strong></td><td>Save the widgets and filters a team watches</td><td>Everyone</td></tr><tr><td><strong>Set retention</strong></td><td>See what runs take up, delete old ones, keep the ones that matter</td><td>Administrators</td></tr></tbody></table><p>A guide about a capability your instance declined on the Setup page (<a href="/operate/capabilities.html#declining-a-capability">Choose what you use</a>) is not listed. With authentication off, every guide is listed for everyone, as every page is.</p><h2 id="on-your-own-data" tabindex="-1">On your own data <a class="header-anchor" href="#on-your-own-data" aria-label="Permalink to &quot;On your own data&quot;">​</a></h2><p>A stop on the page of a project, a run, an execution, a failure cluster or a test opens one of yours, which the guide finds as it starts: the project updated last, the newest finished run, a failure of the newest failed run, the open cluster seen last, the flakiest test, or the first saved dashboard you can edit. When your instance holds none yet, such as no saved dashboard, the stop shows in the middle of the screen instead, with a line saying when that part of the page appears.</p><p>The guides walk the dashboard&#39;s own screens. For the work done elsewhere, in your Playwright project or your CI, a stop shows the screen with the command or the setting, and its docs link has the rest.</p><h2 id="suggested-on-a-page" tabindex="-1">Suggested on a page <a class="header-anchor" href="#suggested-on-a-page" aria-label="Permalink to &quot;Suggested on a page&quot;">​</a></h2><p>Three pages suggest a guide, or a question for the <a href="./assistant.html">assistant</a>, when what they show calls for one:</p><table tabindex="0"><thead><tr><th>Page</th><th>When</th><th>Offers</th></tr></thead><tbody><tr><td>Setup</td><td>A capability is neither in use nor declined</td><td><strong>Ask</strong>: which of them your runs would use, and what each one needs</td></tr><tr><td>A failure cluster</td><td>Its diagnosis read no commits, and no SCM token is set for the project or the instance</td><td><strong>Show me</strong>: Add the SCM token</td></tr><tr><td>An execution</td><td>It timed out, or its leading clue comes from the network, the server logs or the console, and the project has not decided on the capture fixtures</td><td><strong>Show me</strong>: Add the capture fixtures</td></tr></tbody></table><p>A fixed rule over what the page already shows decides; no AI model is called. A page shows one suggestion at most, and a browser at most three a week. <strong>Don&#39;t show again</strong> hides one for good: the dismissal is kept on the server for your account, so it stays hidden in every browser, and with authentication off it is hidden for every visitor. A suggestion whose guide is not listed for you does not show. A question needs the assistant and an AI model to answer it, so declining the assistant or AI on the Setup page turns the Setup suggestion off; the two that offer a guide need no model and keep showing, and <strong>Don&#39;t show again</strong> still hides them.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./assistant.html">Assistant</a>: answers questions, and shows its answer on your screens with <strong>Show me</strong></li><li><a href="./ui-overview.html">UI overview</a>: a map of every page a guide visits</li><li><a href="/reference/keyboard-shortcuts.html">Keyboard shortcuts</a>: the command palette and the go-to keys</li></ul>',19))])}const b=a(l,[["render",u]]);export{y as __pageData,b as default};
